      SUBROUTINE RINV3CC     CALCULATES INVERSE OF THIRD-ORDER TRANSFER MATRIXCC ----------------------------------------------------------------------      INCLUDE 'RS.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'US.CIN'C-----------------------------------------------------------------------      REAL            UR(6)C      DO 20 I1 = 1, 5      DO 20 I234 = 1, 56      SS = 0.0      DO 10 I5 = 1, 5      SS = SS + RS(I1,I5)*US(I5,I234)   10 CONTINUE      UT(I1,I234) = - SS   20 CONTINUEC      DO 30 J = 1, 5      DO 30 K = 1, 56      US(J,K) = 0.0   30 CONTINUEC      DO 100 I1 = 1, 5      DO 100 I2 = 1, 6      INDA = 0      DO 100 I7 = 1, 6      DO 60 I6 = 1, I7      UR(I6) = 0.0      DO 60 I5 = 1, I6      INDA = INDA + 1      UR(I6) = UR(I6) + UT(I1,INDA)*RS(I5,I2)   60 CONTINUEC      DO 90 I3 = 1, 6      URR = 0.0      DO 70 I6 = 1, I7      URR = URR + UR(I6)*RS(I6,I3)   70 CONTINUE      IF (URR .EQ. 0.0) GO TO 90C      DO 80 I4 = 1, 6      I234 = INDEX3(I2,I3,I4)      US(I1,I234) = US(I1,I234) + URR*RS(I7,I4)   80 CONTINUE   90 CONTINUE  100 CONTINUEC      DO 150 J = 1, 5      INDA = 0      DO 150 I2 = 1, 6      DO 150 I1 = 1, I2      INDA = INDA + 1      INDB = 0      DO 130 J2 = 1, 6      DO 130 J1 = 1, J2      INDB = INDB + 1      IF (I1 .LE. 5) THEN        I123 = INDEX3(I2,J1,J2)        US(J,I123) = US(J,I123) - TS(J,INDA)*TT(I1,INDB)      ENDIF  130 CONTINUE      INDB = 0      DO 140 J2 = 1, 6      DO 140 J1 = 1, J2      INDB = INDB + 1      IF (I2 .LE. 5) THEN        I123 = INDEX3(I1,J1,J2)        US(J,I123) = US(J,I123) - TS(J,INDA)*TT(I2,INDB)      ENDIF  140 CONTINUE  150 CONTINUEC      RETURN      END